        <style>
            /* Scope strictly to the provided class */
            a.glow-buttoon {
                box-sizing: border-box;
                position: relative;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 6px;
                height: 36px;
                padding: 1rem;
                border-radius: 0.75rem;
                background: transparent;
                border: none;
                color: #ffffff;
                text-decoration: none;
                white-space: nowrap;
                font-size: 14px;
                letter-spacing: 0.14px;
                font-weight: 550;
                font-family:
                    "Esklarheitgroteskvar Xlt",
                    system-ui,
                    -apple-system,
                    Segoe UI,
                    Roboto,
                    Ubuntu,
                    Cantarell,
                    Noto Sans,
                    Helvetica Neue,
                    Arial,
                    sans-serif;
                cursor: pointer;
                overflow: visible;
                transform-origin: center center;
                /* Breathing scale animation (idle) */
                animation: scan-breathe 12s ease-in-out infinite;
                will-change: transform;
                -webkit-font-smoothing: antialiased;
                -moz-osx-font-smoothing: grayscale;
                -webkit-tap-highlight-color: transparent;
            }

            /* Pulsing outer glow (behind) */
            a.glow-buttoon::before {
                content: "";
                position: absolute;
                inset: 0;
                border-radius: inherit;
                pointer-events: none;
                /* Matches: 0 0 24px 6px rgba(171,230,161,.6), inset 0 0 16px 2px rgba(171,230,161,.4) */
                box-shadow:
                    0 0 24px 6px rgba(171, 230, 161, 0.6),
                    inset 0 0 16px 2px rgba(171, 230, 161, 0.4);
                opacity: 0;
                animation: scan-glow 6s ease-in-out infinite;
            }

            /* Sweeping shine overlay (above content, mostly transparent) */
            a.glow-buttoon::after {
                content: "";
                position: absolute;
                inset: 0;
                border-radius: inherit;
                pointer-events: none;
                background: linear-gradient(
                    135deg,
                    rgba(0, 0, 0, 0) 0%,
                    rgba(0, 0, 0, 0) 40%,
                    rgba(171, 230, 161, 0.5) 50%,
                    rgba(0, 0, 0, 0) 60%,
                    rgba(0, 0, 0, 0) 100%
                );
                background-size: 200% 200%;
                animation: scan-shine 3.6s ease-in-out infinite;
            }

            /* Larger amplitude when hovered, mirroring the original */
            a.glow-buttoon:hover {
                animation-name: scan-breathe-hover;
            }

            /* Keyframes to match the original motion design */
            @keyframes scan-breathe {
                0% {
                    transform: scale(1);
                }
                50% {
                    transform: scale(1.02);
                }
                100% {
                    transform: scale(1);
                }
            }

            @keyframes scan-breathe-hover {
                0% {
                    transform: scale(1.04);
                }
                50% {
                    transform: scale(1.06);
                }
                100% {
                    transform: scale(1.04);
                }
            }

            @keyframes scan-glow {
                0% {
                    opacity: 0;
                }
                50% {
                    opacity: 0.3;
                }
                100% {
                    opacity: 0;
                }
            }

            @keyframes scan-shine {
                0% {
                    background-position: 200% 200%;
                }
                100% {
                    background-position: -100% -100%;
                }
            }

            /* Hide on tablet and below (≤ 991px) */
            @media (max-width: 991px) {
                a.glow-buttoon {
                    display: none !important;
                }
            }
        </style>

