                --navbar-radius-speed: 200ms;
                --navbar-radius-ease: ease;
                --navbar-chevron-speed: var(--navbar-radius-speed);

                --navbar-scroll-speed: 0.25s; /* scrolled bar speed */
                --navbar-scroll-ease: var(--mega-ease);
                --navbar-scroll-line: rgba(255, 255, 255, 0.16);
                --navbar-scroll-btm-pad: calc(0.75rem - 0.25rem * var(--navbar-scroll-hide-top-bar));
                --navbar-scroll-hide-top-bar: 0; /* 1 = hide top strip when scrolled, 0 = keep */
            }

            /* 1. Mega menu */
            .nav-mega-stack {
                position: absolute;
                top: 100%;
                left: 0;
                right: 0;
                height: 0;
                overflow: hidden;

                transition:
                    height var(--mega-height-speed) var(--mega-ease),
                    left var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease),
                    right var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease),
                    border-bottom-left-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease),
                    border-bottom-right-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);

                background-color: var(--color-scheme-1--dark-second, #0e121a);
                border-bottom-left-radius: var(--mega-radius);
                border-bottom-right-radius: var(--mega-radius);
            }

            .nav-mega-panel {
                position: absolute !important;
                top: 0 !important;
                left: 0 !important;
                right: 0 !important;
                width: 100%;
                height: auto !important;
                display: flex !important;
                background-color: transparent !important;
                opacity: 0;
                pointer-events: none;
                transform: translateX(var(--mega-shift-x, 0px));
                transition:
                    opacity var(--mega-fade-speed) var(--mega-ease),
                    transform var(--mega-slide-speed) var(--mega-ease);
            }

            .nav-mega-panel[data-mega-active] {
                opacity: 1;
                pointer-events: auto;
                transform: translateX(0px);
            }

            .navbar-v2 .nav-mega-panel.w--open {
                transition:
                    opacity var(--mega-fade-speed) var(--mega-ease),
                    transform var(--mega-slide-speed) var(--mega-ease);
            }

            /* 2. Navbar corners */
            .navbar-v2 {
                transition:
                    border-bottom-left-radius var(--navbar-radius-speed) var(--navbar-radius-ease)
                        var(--mega-height-speed),
                    border-bottom-right-radius var(--navbar-radius-speed) var(--navbar-radius-ease)
                        var(--mega-height-speed),
                    translate var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
            }

            .navbar-v2.is-dropdown-open {
                border-bottom-left-radius: 0px !important;
                border-bottom-right-radius: 0px !important;
                transition-delay: 0s, 0s, 0s;
                transition-duration: 0s, 0s, var(--navbar-scroll-duration, 0s);
            }

            /* 3. Chevron */
            .nav_dropdown-chevron {
                transition: transform var(--navbar-chevron-speed) var(--navbar-radius-ease);
                transform-origin: 50% 50%;
            }

            .navbar-v2_dropdown.is-open .nav_dropdown-chevron {
                transform: rotate(180deg);
            }

            /* 4. Fluid column gap */
            @media (min-width: 992px) {
                .navbar-v2_dropdown-content-left {
                    --gap-min: 24px;
                    --gap-max: 48px;
                    --gap-delta: 24;

                    column-gap: clamp(
                        var(--gap-min),
                        calc(var(--gap-min) + (100vw - 992px) * var(--gap-delta) / 208),
                        var(--gap-max)
                    ) !important;
                }
            }

            /* 5. data-hide-narrow */
            @media (min-width: 992px) and (max-width: 1130px) {
                [data-hide-narrow] {
