            /* 6. Trigger colour */
            .navbar-v2_dropdown-toggle:hover,
            .navbar-v2_dropdown.is-open .navbar-v2_dropdown-toggle {
                color: var(--color-scheme-1--light-green, #c7ffbe) !important;
            }

            /* 7. Scrolled bar (desktop) */
            @media (min-width: 992px) {
                .navbar-v2 {
                    --navbar-scroll-duration: var(--navbar-scroll-speed);
                }

                .navbar-v2.is-scrolled {
                    translate: 0
                        calc(
                            -1 * (var(--navbar-lift-base, 0px) + var(--navbar-lift-strip, 0px) *
                                        var(--navbar-scroll-hide-top-bar, 1))
                        );
                }

                .navbar-v2.is-scrolled:has(.navbar-v2_top-bar :focus-visible) {
                    translate: 0 calc(-1 * var(--navbar-lift-base, 0px));
                }

                .navbar-v2::before {
                    content: "";
                    display: block;
                    position: absolute;
                    z-index: -1;
                    grid-area: auto;
                    top: calc(-1 * var(--navbar-lift-base, 0px));
                    bottom: -1px;
                    left: calc(50% - 50vw);
                    right: calc(50% - 50vw);
                    border-bottom: 1px solid var(--navbar-scroll-line);
                    background-color: inherit;
                    opacity: 0;
                    pointer-events: none;
                    transition: opacity var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
                }

